import {activityLabel} from '/activity-labels.js';
import {systemLogo} from '/core.js';
import {mountProfessionalReports,mountReportBranding} from '/professional-reports.js';
import {typographyControls,bindTypographyControls} from '/typography-controls.js';
import {classAdmissionPanel,workspaceNavigation,renderWorkspaceTool,bindMetricDrilldowns,previewBulk} from '/workspace-tools.js';
import {workspaceSearch,temporaryPasswordView,actionMenu,appearanceActions,uiIcon,api,applyTypography,bindLogin,cycleLocale,cycleTheme,esc,eventSource,fmtDate,fmtDateTime,downloadUrl,getLocale,initLocale,initTheme,langButton,loginView,modal,setToken,t,themeIcon,toast} from '/core.js';
import {renderContent} from '/renderer.js';
import {bindDiscovery,discoveryToolbar,refreshDiscoveries} from '/discovery.js';
import {mountReportChartWorkspace} from '/report-charts.js';
initTheme();initLocale();
const app=document.querySelector('#app');
const state={user:null,view:'overview',settings:null,courses:[],classes:[],staff:[],students:[],admin:null,stop:null,builder:null,builderSelection:null,builderTab:'tree'};
const icon=body=>`<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${body}</svg>`;
const icons={
  overview:icon('<path d="M4 13h6V4H4zM14 20h6v-9h-6zM14 4h6v3h-6zM4 20h6v-3H4z"/>'),
  live:icon('<circle cx="12" cy="12" r="3"/><path d="M5.6 5.6a9 9 0 0 0 0 12.8M18.4 5.6a9 9 0 0 1 0 12.8M8.5 8.5a5 5 0 0 0 0 7M15.5 8.5a5 5 0 0 1 0 7"/>'),
  courses:icon('<path d="M4 5.5A2.5 2.5 0 0 1 6.5 3H20v16H6.5A2.5 2.5 0 0 0 4 21.5z"/><path d="M4 5.5v16M8 7h8M8 11h6"/>'),
  classes:icon('<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 10h18M7 14h3M14 14h3M7 18h3"/>'),
  people:icon('<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M22 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75"/>'),
  reports:icon('<path d="M4 19V9M10 19V5M16 19v-7M22 19H2"/>'),
  messages:icon('<path d="M21 15a4 4 0 0 1-4 4H8l-5 3V7a4 4 0 0 1 4-4h10a4 4 0 0 1 4 4z"/><path d="M8 9h8M8 13h5"/>'),
  settings:icon('<circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.7 1.7 0 0 0 .34 1.88l.06.06-2.12 2.12-.06-.06a1.7 1.7 0 0 0-1.88-.34 1.7 1.7 0 0 0-1 1.55V20.3h-3v-.09a1.7 1.7 0 0 0-1-1.55 1.7 1.7 0 0 0-1.88.34l-.06.06-2.12-2.12.06-.06A1.7 1.7 0 0 0 7.1 15a1.7 1.7 0 0 0-1.55-1H5.5v-3h.05a1.7 1.7 0 0 0 1.55-1 1.7 1.7 0 0 0-.34-1.88l-.06-.06 2.12-2.12.06.06a1.7 1.7 0 0 0 1.88.34 1.7 1.7 0 0 0 1-1.55V4.7h3v.09a1.7 1.7 0 0 0 1 1.55 1.7 1.7 0 0 0 1.88-.34l.06-.06 2.12 2.12-.06.06A1.7 1.7 0 0 0 19.4 10a1.7 1.7 0 0 0 1.55 1H21v3h-.05a1.7 1.7 0 0 0-1.55 1z"/>')
};
icons.staff=icons.people;
const nav=['overview','live','courses','classes','staff','people','reports','messages','settings'];
const labels={overview:'System overview',live:'Live classes',courses:'Courses',classes:'Classes',staff:'Trainers & staff',people:'Participants',reports:'Analytics',messages:'Messages',settings:'Settings'};
for(const [key,text] of Object.entries({'workspace-groups':'Groups','workspace-admissions':'Admission requests','workspace-audit':'Audit & history','workspace-archive':'Archive & restore'})){nav.push(key);labels[key]=text;icons[key]=uiIcon(key==='workspace-admissions'?'bell':'user')}
const label=k=>t(labels[k]||k);
const roleName=role=>({super_admin:'Super administrator',administrator:'Administrator',trainer:'Trainer',assistant:'Assistant trainer',course_editor:'Course Editor'})[role]||'Trainer';
const canAdmin=()=>['super_admin','administrator'].includes(state.user?.staff_role);
async function boot(){const me=await api('/api/me').catch(()=>({user:null}));if(!me.user||me.user.role!=='trainer'||!['super_admin','administrator'].includes(me.user.staff_role))return login();state.user=me.user;if(me.user.must_change_password)return temporaryPasswordView(app,me.user,async u=>{state.user=u;await enter()});await enter()}
function login(){setToken('');app.innerHTML=loginView({title:t('Admin workspace'),subtitle:t('Global administration and live delivery oversight.')});bindLogin(app,{requiredRole:'trainer',onSuccess:async u=>{if(!['super_admin','administrator'].includes(u.staff_role)){setToken('');toast(t('Administrator access is required for this area.'),'error');return}state.user=u;await enter()},onLocaleChange:login})}
async function enter(){await refreshBase();renderShell();bindDiscovery(app);state.stop?.();state.stop=eventSource(()=>refreshCurrent(false));setInterval(()=>api('/api/heartbeat',{method:'POST'}).catch(()=>{}),45000);await navigate('overview');const requested=Number(new URLSearchParams(location.search).get('class_id')||location.hash.match(/^#class-(\d+)$/)?.[1]||0);if(requested){try{await manageClass(requested)}catch(error){toast(error.message,'error')}}}
async function refreshBase(){const [settings,courses,classes,staff,students]=await Promise.all([api('/api/settings'),api('/api/courses'),api('/api/classes'),api('/api/staff'),api('/api/students')]);state.settings=settings;state.courses=courses.courses;state.classes=classes.classes;state.staff=staff.staff;state.students=students.students;applyTypography(settings.typography||{},'ui')}
function renderShell(){
 const brand=esc(state.settings?.brand?.name||'Training Engine ONE'),workspace=t('Admin workspace');
 const menuBody=`<button class="one-menu-item" data-action="global-search">${esc(t('Search'))}</button><div class="one-menu-profile"><span class="avatar">${esc((state.user.display_name||state.user.username).slice(0,1))}</span><div><strong><bdi>${esc(state.user.display_name||state.user.username)}</bdi></strong><small>${esc(t(({super_admin:'Super administrator',administrator:'Administrator',trainer:'Trainer',assistant:'Assistant trainer',course_editor:'Course Editor'})[state.user.staff_role]||'Trainer'))}</small></div></div>${appearanceActions()}<div class="one-menu-separator"></div><a class="one-menu-item" href="/trainer">${esc(t('Trainer workspace'))}</a><button class="one-menu-item danger" data-action="logout">${esc(t('Sign out'))}</button>`;
 document.title=`${brand} — ${workspace}`;
 app.innerHTML=`<div class="mobile-head"><div class="brand">${systemLogo()}<span>${brand}</span></div>${actionMenu(t('Menu'),menuBody,{compact:true})}</div><div class="shell"><aside class="side"><div class="brand">${systemLogo()}<span>${brand}</span></div><div class="workspace-context"><span class="workspace-context-dot"></span><div><strong>${workspace}</strong><small>${esc(t('Local workspace'))}</small></div></div><nav class="nav">${nav.map(n=>`<button data-nav="${n}"><span>${icons[n]}</span><span>${esc(label(n))}</span></button>`).join('')}<a class="workspace-profile-link" href="/profile">${uiIcon('user')}<span>${esc(t('My profile'))}</span></a></nav><div class="side-foot"><div class="workspace-identity"><span class="avatar">${esc((state.user.display_name||state.user.username).slice(0,1))}</span><div><strong><bdi>${esc(state.user.display_name||state.user.username)}</bdi></strong><small>${esc(t(({super_admin:'Super administrator',administrator:'Administrator',trainer:'Trainer',assistant:'Assistant trainer',course_editor:'Course Editor'})[state.user.staff_role]||'Trainer'))}</small></div></div>${actionMenu(t('Menu'),menuBody)}</div></aside><main class="main"><div class="topbar"><div><span class="topbar-workspace">${workspace}</span><span class="topbar-divider">/</span><span class="muted small" id="crumb">${workspace}</span></div><div class="topbar-actions"><button class="btn workspace-search" data-action="global-search">⌕ <span>${esc(t('Search'))}</span></button>${actionMenu(t('Menu'),menuBody,{compact:true})}</div></div><div id="page" class="page"></div></main></div><nav class="bottom-nav">${['overview','live','courses','classes'].map(n=>`<button data-nav="${n}"><span>${icons[n]}</span><span>${esc(label(n))}</span></button>`).join('')}<button data-action="mobile-more">${uiIcon('menu')}<span>${esc(t('More'))}</span></button></nav>`;bindGlobal()
}
function showMobileMenu(){const w=modal(t('More'),`<div class="mobile-menu-list">${nav.map(n=>`<button class="mobile-menu-item" data-mobile-nav="${n}"><span>${icons[n]}</span><span>${esc(label(n))}</span></button>`).join('')}<a class="mobile-menu-item" href="/trainer"><span>↗</span><span>${esc(t('Trainer workspace'))}</span></a><button class="mobile-menu-item danger" data-mobile-logout><span>↪</span><span>${esc(t('Sign out'))}</span></button></div>`,{confirmText:t('Close'),onConfirm:null});w.querySelectorAll('[data-mobile-nav]').forEach(b=>b.addEventListener('click',async()=>{w.remove();await navigate(b.dataset.mobileNav)}));w.querySelector('[data-mobile-logout]')?.addEventListener('click',async()=>{await api('/api/logout',{method:'POST'}).catch(()=>{});setToken('');w.remove();login()})}
function bindGlobal(){app.onclick=async e=>{const navEl=e.target.closest('[data-nav]');if(navEl){await navigate(navEl.dataset.nav);return}const act=e.target.closest('[data-action]');if(!act)return;try{if(act.dataset.action==='mobile-more'){showMobileMenu()}else if(act.dataset.action==='language'){cycleLocale();renderShell();await navigate(state.view)}else if(act.dataset.action==='theme'){cycleTheme();renderShell();await navigate(state.view)}else if(act.dataset.action==='logout'){await api('/api/logout',{method:'POST'}).catch(()=>{});setToken('');login()}else await action(act.dataset.action,act)}catch(err){toast(err.message,'error')}}}
async function navigate(v){state.view=v;document.querySelectorAll('[data-nav]').forEach(x=>x.classList.toggle('active',x.dataset.nav===v));const c=document.querySelector('#crumb');if(c)c.textContent=label(v);if(v.startsWith('workspace-'))return renderWorkspaceTool(v,document.querySelector('#page'),state.user,openWorkspaceRecord);await refreshCurrent(true)}
async function refreshCurrent(busy=false){const page=document.querySelector('#page');if(!page)return;if(busy)page.innerHTML=`<div class="card"><div class="empty">${esc(t('Loading…'))}</div></div>`;await refreshBase();if(state.view.startsWith('workspace-'))return renderWorkspaceTool(state.view,page,state.user,openWorkspaceRecord);if(state.view==='overview')await overview();else if(state.view==='live')await live();else if(state.view==='courses')await courses();else if(state.view==='classes')await classes();else if(state.view==='staff')await people('staff');else if(state.view==='people')await people();else if(state.view==='reports')await reports();else if(state.view==='messages')await messages();else if(state.view==='settings')await settings();refreshDiscoveries(app);bindMetricDrilldowns(page,openWorkspaceRecord)}
const head=(title,sub,actions='')=>`<div class="page-head"><div><h1>${esc(title)}</h1><p>${esc(sub||'')}</p></div><div class="topbar-actions">${actions}</div></div>`;
async function overview(){state.admin=await api('/api/dashboard/admin');const d=state.admin,page=document.querySelector('#page');page.innerHTML=`${head(t('System overview'),t('Global administration and live delivery oversight.'))}<section class="admin-hero"><div class="admin-hero-main"><div class="eyebrow">${esc(t('Super Admin'))}</div><h2 class="admin-hero-title">${esc(t('Live operations'))}</h2><p class="muted">${esc(t('See every running class without interrupting delivery.'))}</p><div class="topbar-actions"><button class="btn primary" data-nav="live">${esc(t('Open operations view'))}</button></div></div><div class="grid two"><div class="card stat"><div class="stat-label">${esc(t('Courses'))}</div><div class="stat-value">${d.counts.courses}</div></div><div class="card stat"><div class="stat-label">${esc(t('Live classes'))}</div><div class="stat-value">${d.counts.live_classes}</div></div><div class="card stat"><div class="stat-label">${esc(t('Participants'))}</div><div class="stat-value">${d.counts.participants}</div></div><div class="card stat"><div class="stat-label">${esc(t('Trainer'))}</div><div class="stat-value">${d.counts.trainers}</div></div></div></section><section style="margin-top:20px"><div class="metric-row"><div><div class="eyebrow">${esc(t('Live monitoring'))}</div><h2>${esc(t('Live classes'))}</h2></div></div><div class="live-class-grid">${liveCards(d.live)}</div></section><section class="card" style="margin-top:20px"><h2>${esc(t('Global activity'))}</h2><div class="activity-log">${d.recent.map(ev=>`<div class="event"><span class="event-dot"></span><div><strong>${esc(String(ev.event_type||'').replaceAll('_',' '))}</strong><div class="small muted">${esc(ev.display_name||'')} · ${esc(ev.class_title||'')}</div></div><span class="tiny muted">${fmtDateTime(ev.created_at)}</span></div>`).join('')||`<div class="empty">${esc(t('No activity yet.'))}</div>`}</div></section>`}
function liveCards(rows=[]){return rows.length?rows.map(c=>`<article class="live-class-card" data-discovery-item data-search="${esc([c.title,c.course_title,c.trainer_name].filter(Boolean).join(' '))}" data-sort-participants="${Number(c.participants||0)}" data-sort-connected="${Number(c.connected||0)}"><div class="metric-row"><div><span class="status-dot live"></span> <strong>${esc(c.title)}</strong><div class="small muted">${esc(c.course_title)} · ${esc(c.trainer_name||'')}</div></div><span class="badge live">${esc(t('Live'))}</span></div><div class="mini-stats"><div class="mini-stat"><strong>${c.connected}/${c.participants}</strong><span class="tiny muted">${esc(t('Connected now'))}</span></div><div class="mini-stat"><strong>${c.working}</strong><span class="tiny muted">${esc(t('Working'))}</span></div><div class="mini-stat"><strong>${c.need_help}</strong><span class="tiny muted">${esc(t('Need help'))}</span></div><div class="mini-stat"><strong>${c.finished}</strong><span class="tiny muted">${esc(t('Finished'))}</span></div></div><button class="btn" data-action="observe-class" data-id="${c.id}">${esc(t('Observe class'))}</button></article>`).join(''):`<div class="card empty">${esc(t('No live classes right now.'))}</div>`}
async function live(){const d=await api('/api/dashboard/admin'),scope='admin-live',toolbar=discoveryToolbar(scope,{placeholder:'Search',sorts:[{value:'participants:desc',label:'Most participants'},{value:'connected:desc',label:'Connected now'}],countLabel:'Live classes'});document.querySelector('#page').innerHTML=`${head(t('Live classes'),t('Observe every active class without changing its classroom flow.'))}${toolbar}<div class="live-class-grid" data-discovery-scope="${scope}">${liveCards(d.live)}</div>`}
async function observeClass(id){const d=await api(`/api/admin/live/${id}`),scope=`admin-live-participants-${id}`,toolbar=discoveryToolbar(scope,{placeholder:'Search',filters:[{key:'status',label:'Status',options:[{value:'working',label:'Working'},{value:'need_help',label:'Need help'},{value:'finished',label:'Finished'},{value:'not_started',label:'Not started'}]}],sorts:[{value:'title:asc',label:'Name A–Z'}],countLabel:'Participants'});const w=modal(`${t('Live monitoring')} · ${d.class.title}`,`<div class="ops-detail">${d.workflow?.current||d.workflow?.next?`<div class="card"><div class="metric-row"><div><div class="eyebrow">${esc(t('Course flow'))}</div><h3>${esc(d.workflow.current?.title||d.workflow.next?.title||'')}</h3></div><span class="badge ${d.workflow.current?'live':'workflow-next-badge'}">${esc(t(d.workflow.current?'Current':'Next'))}</span></div>${d.workflow.next&&d.workflow.current?`<div class="small muted" style="margin-top:8px">${esc(t('Next'))}: ${esc(d.workflow.next.title)}</div>`:''}</div>`:''}<div class="grid four"><div class="card stat"><div class="stat-label">${esc(t('Participants'))}</div><div class="stat-value">${d.students.length}</div></div><div class="card stat"><div class="stat-label">${esc(t('Connected now'))}</div><div class="stat-value">${d.students.filter(x=>x.connected).length}</div></div><div class="card stat"><div class="stat-label">${esc(t('Need help'))}</div><div class="stat-value">${d.students.filter(x=>x.progress_status==='need_help').length}</div></div><div class="card stat"><div class="stat-label">${esc(t('Finished'))}</div><div class="stat-value">${d.students.filter(x=>x.progress_status==='finished').length}</div></div></div>${toolbar}<div class="ops-participants" data-discovery-scope="${scope}">${d.students.map(x=>`<article class="ops-participant" data-discovery-item data-search="${esc(x.display_name||'')}" data-filter-status="${esc(x.progress_status||'not_started')}" data-sort-title="${esc(x.display_name||'')}"><div class="metric-row"><strong>${esc(x.display_name)}</strong><span class="status-dot ${x.connected?'live':''}"></span></div><div class="ops-tags"><span class="badge">${esc(t(statusText(x.progress_status)))}</span>${x.path_id?`<span class="badge">${esc(x.path_id)}</span>`:''}${x.step_total?`<span class="badge">${x.step_index+1}/${x.step_total}</span>`:''}</div></article>`).join('')}</div></div>`,{confirmText:t('Close'),onConfirm:null,wide:true});bindDiscovery(w);refreshDiscoveries(w)}
function statusText(v){return ({working:'Working',need_help:'Need help',finished:'Finished',not_started:'Not started'})[v]||v}
async function courses(){
  const scope='admin-courses',toolbar=discoveryToolbar(scope,{placeholder:'Search',filters:[{key:'status',label:'Status',options:[{value:'active',label:'Active'},{value:'archived',label:'Archived'}]}],sorts:[{value:'title:asc',label:'Name A–Z'},{value:'title:desc',label:'Name Z–A'},{value:'classes:desc',label:'Most classes'},{value:'versions:desc',label:'Most versions'}],countLabel:'Courses'});
  const rows=state.courses.map(c=>`<article class="card course-card ${c.archived_at?'muted':''}" data-discovery-item data-search="${esc([c.title,c.description,c.latest_version].filter(Boolean).join(' '))}" data-filter-status="${c.archived_at?'archived':'active'}" data-sort-title="${esc(c.title||'')}" data-sort-classes="${Number(c.class_count||0)}" data-sort-versions="${Number(c.version_count||0)}"><div class="metric-row"><label class="bulk-check"><input type="checkbox" data-bulk-course="${c.id}"><span class="badge">${esc(t(c.archived_at?'Archived':'Course'))}</span></label><span class="tiny muted">${esc(c.latest_version||t('Draft'))}</span></div><div><div class="course-title">${esc(c.title)}</div><p class="small muted">${esc(c.description||'')}</p></div><div class="meta"><span>${c.version_count} ${esc(t('Versions'))}</span><span>•</span><span>${c.class_count} ${esc(t('Classes'))}</span></div><div class="form-actions"><button class="btn primary" data-action="open-builder" data-id="${c.id}">${esc(t('Course Builder'))}</button><button class="btn" data-action="manage-course" data-id="${c.id}">${esc(t('Manage'))}</button></div></article>`).join('');
  document.querySelector('#page').innerHTML=`${head(t('Courses'),t('Create, version, validate and visually edit reusable courses.'),`<button class="btn" data-action="bulk-course-archive">${esc(t('Archive selected'))}</button><button class="btn" data-action="import-course">${esc(t('Import course package'))}</button><button class="btn primary" data-action="new-course">${esc(t('New course'))}</button>`)}${toolbar}<div class="grid three" data-discovery-scope="${scope}">${rows}</div>${state.courses.length?'':`<div class="card empty">${esc(t('No courses yet. Import your first course package when you are ready.'))}</div>`}`
}
async function openBuilder(courseId){location.href=`/builder?course_id=${Number(courseId)}`}
function nextVersion(v){const m=String(v||'1.0').match(/^(\d+)\.(\d+)/);return m?`${m[1]}.${Number(m[2])+1}`:`${v}.1`}
function modules(){return state.builder?.content?.course?.modules||[]}
function renderBuilder(){const b=state.builder,page=document.querySelector('#page');if(!b)return navigate('courses');page.innerHTML=`${head(`${t('Course Builder')} · ${b.content.course?.title||''}`,`${t('Draft')} ${b.version.version}`,`<button class="btn" data-action="validate-builder">${esc(t('Validation'))}</button><button class="btn" data-action="save-builder">${esc(t('Save draft'))}</button><button class="btn primary" data-action="publish-builder">${esc(t('Publish version'))}</button>`)}<div class="builder-tabs"><button class="${state.builderTab==='tree'?'active':''}" data-action="builder-tab" data-tab="tree">${esc(t('Tree view'))}</button><button class="${state.builderTab==='edit'?'active':''}" data-action="builder-tab" data-tab="edit">${esc(t('Edit view'))}</button><button class="${state.builderTab==='preview'?'active':''}" data-action="builder-tab" data-tab="preview">${esc(t('Preview mode'))}</button></div>${state.builderTab==='tree'?builderTree():state.builderTab==='edit'?builderEdit():builderPreview()}`;}
function builderTree(){return `<div class="workflow-shell"><section class="tree-panel"><div class="tree-toolbar"><button class="btn primary" data-action="builder-add-module">${esc(t('Add milestone'))}</button></div>${modules().map((m,mi)=>`<div class="tree-module"><div class="tree-module-head"><strong>${esc(m.title||`Module ${mi+1}`)}</strong><div class="tree-node-actions"><button class="btn" data-action="builder-select" data-kind="module" data-mi="${mi}">${esc(t('Edit'))}</button><button class="btn" data-action="builder-add-item" data-mi="${mi}" data-kind="activity">+ ${esc(t('Activity'))}</button><button class="btn" data-action="builder-add-item" data-mi="${mi}" data-kind="mission">+ ${esc(t('Mission'))}</button><button class="btn" data-action="builder-add-item" data-mi="${mi}" data-kind="path">+ ${esc(t('Participant path'))}</button></div></div>${(m.activities||[]).map((a,ai)=>treeNode('activity',a,mi,ai)).join('')}${(m.missions||[]).map((a,ai)=>treeNode('mission',a,mi,ai)).join('')}${(m.paths||[]).map((a,ai)=>treeNode('path',a,mi,ai)).join('')}</div>`).join('')}</section><section class="editor-panel"><div class="eyebrow">${esc(t('Workflow tree'))}</div>${workflowPreview()}</section></div>`}
function treeNode(kind,item,mi,ii){return `<div class="tree-node"><span class="node-icon">${kind==='activity'?'A':kind==='mission'?'M':'P'}</span><button class="btn" style="justify-content:flex-start;border:0" data-action="builder-select" data-kind="${kind}" data-mi="${mi}" data-ii="${ii}">${esc(item.title||item.id||t('Untitled'))}</button><div class="tree-node-actions"><button class="btn" data-action="builder-move" data-dir="up" data-kind="${kind}" data-mi="${mi}" data-ii="${ii}">↑</button><button class="btn" data-action="builder-move" data-dir="down" data-kind="${kind}" data-mi="${mi}" data-ii="${ii}">↓</button><button class="btn" data-action="builder-duplicate" data-kind="${kind}" data-mi="${mi}" data-ii="${ii}">⧉</button><button class="btn danger" data-action="builder-delete" data-kind="${kind}" data-mi="${mi}" data-ii="${ii}">×</button></div></div>`}
function workflowPreview(){const m=modules()[0];if(!m)return `<div class="empty">${esc(t('Add milestone'))}</div>`;const wf=m.workflow;if(wf?.nodes?.length)return `<div class="workflow-canvas"><div class="workflow-lanes"><div class="workflow-lane">${wf.nodes.map(n=>`<div class="workflow-node-card"><span class="badge">${esc(n.type||'node')}</span><strong>${esc(n.title||n.id)}</strong></div>`).join('')}</div></div></div>`;const seq=[...(m.activities||[]),...(m.missions||[])];return `<div class="workflow-canvas"><div class="workflow-lane">${seq.map(x=>`<div class="workflow-node-card"><strong>${esc(x.title||x.id)}</strong></div>`).join('')||`<div class="empty">${esc(t('No activity yet.'))}</div>`}</div></div>`}
function selection(){const s=state.builderSelection;if(!s)return null;const m=modules()[s.mi];if(!m)return null;if(s.kind==='module')return m;const arr=s.kind==='activity'?m.activities:s.kind==='mission'?m.missions:m.paths;return arr?.[s.ii]||null}
function builderEdit(){const sel=selection();if(!sel)return `<div class="card empty">${esc(t('Choose an item from the course flow. Participant devices will follow your live classroom automatically.'))}</div>`;const s=state.builderSelection;return `<div class="editor-panel"><div class="form-grid"><div class="field"><label>${esc(t('Name'))}</label><input class="input" id="beTitle" value="${esc(sel.title||'')}"></div>${s.kind==='activity'?`<div class="field"><label>${esc(t('Node type'))}</label><select class="select" id="beType">${['presentation','announcement','poll','single_choice','multiple_choice','true_false','short_answer','long_answer','rating','reaction','confidence','ranking','timer','reveal','team_challenge','checklist','participant_choice','practice_gate'].map(x=>`<option value="${x}" ${sel.type===x?'selected':''}>${esc(activityLabel(x))}</option>`).join('')}</select></div>`:''}<div class="field span-2"><label>${esc(t('Description'))}</label><textarea class="textarea" id="beBody">${esc(sel.content?.body_md||sel.goal||'')}</textarea></div></div><div class="form-actions"><button class="btn primary" data-action="builder-apply-edit">${esc(t('Apply'))}</button></div></div>`}
function builderPreview(){const m=modules()[0],item=m?.activities?.[0];return `<div class="builder-preview">${item?renderContent(item.content||{heading:item.title},{versionId:state.builder.version.id}):`<div class="empty">${esc(t('No item'))}</div>`}</div>`}
async function saveBuilder(){const r=await api(`/api/course-versions/${state.builder.version.id}/draft`,{method:'PUT',json:{content:state.builder.content}});state.builder.dirty=false;toast(`${t('Draft saved.')} #${r.revision}`,'success')}
async function validateBuilder(){const blob=JSON.stringify(state.builder.content);const r=await fetch('/api/courses/validate',{method:'POST',headers:{'X-Session-Token':sessionStorage.getItem('training_engine_session')||'','X-File-Name':'course.json','Content-Type':'application/json'},body:blob});const d=await r.json();modal(t('Validation'),`<div class="grid two"><div class="card"><strong>${d.errors?.length||0}</strong><div class="muted">${esc(t('Blockers'))}</div></div><div class="card"><strong>${d.warnings?.length||0}</strong><div class="muted">${esc(t('Warnings'))}</div></div></div><div class="list" style="margin-top:14px">${[...(d.errors||[]),...(d.warnings||[])].map(x=>`<div class="list-row"><span>${esc(x)}</span></div>`).join('')||`<div class="empty">${esc(t('Ready to publish'))}</div>`}</div>`,{wide:true})}
async function classes(){
  const scope='admin-classes',toolbar=discoveryToolbar(scope,{placeholder:'Search',filters:[{key:'status',label:'Status',options:[{value:'draft',label:'Draft'},{value:'scheduled',label:'Scheduled'},{value:'active',label:'Active'},{value:'completed',label:'Completed'},{value:'archived',label:'Archived'}]}],sorts:[{value:'title:asc',label:'Name A–Z'},{value:'start:desc',label:'Newest date'},{value:'participants:desc',label:'Most participants'}],countLabel:'Classes'});
  const body=state.classes.map(c=>`<tr data-discovery-item data-search="${esc([c.title,c.course_title,c.trainer_name,c.location,c.lifecycle_status].filter(Boolean).join(' '))}" data-filter-status="${esc(c.lifecycle_status||'')}" data-sort-title="${esc(c.title||'')}" data-sort-start="${esc(c.start_date||'')}" data-sort-participants="${Number(c.student_count||0)}"><td><input type="checkbox" data-bulk-class="${c.id}"></td><td><strong>${esc(c.title)}</strong>${c.location?`<div class="tiny muted">${esc(c.location)}</div>`:''}</td><td>${esc(c.course_title)} · v${esc(c.version)}</td><td><span class="badge">${esc(t(({draft:'Draft',scheduled:'Scheduled',active:'Active',completed:'Completed',archived:'Archived'})[c.lifecycle_status]||c.lifecycle_status))}</span></td><td>${fmtDate(c.start_date)}${c.end_date&&c.end_date!==c.start_date?` – ${fmtDate(c.end_date)}`:''}</td><td>${esc(c.trainer_name||'—')}</td><td>${c.student_count}/${c.capacity}</td><td>${c.trainer_count}</td><td><button class="btn" data-action="manage-class" data-id="${c.id}">${esc(t('Manage'))}</button></td></tr>`).join('');
  document.querySelector('#page').innerHTML=`${head(t('Classes'),t('Create and manage each delivery with its trainers, participants, sessions, teams and exact course version.'),`<button class="btn" data-action="bulk-class-archive">${esc(t('Archive selected'))}</button><button class="btn primary" data-action="add-class">${esc(t('Create class'))}</button>`)}${toolbar}<div class="card collection-card"><div class="table-wrap"><table class="table"><thead><tr><th></th><th>${esc(t('Class name'))}</th><th>${esc(t('Course'))}</th><th>${esc(t('Status'))}</th><th>${esc(t('Dates'))}</th><th>${esc(t('Lead trainer'))}</th><th>${esc(t('Participants'))}</th><th>${esc(t('Trainers'))}</th><th></th></tr></thead><tbody data-discovery-scope="${scope}">${body}</tbody></table></div></div>`
}
async function people(kind='participants'){
  const staffScope='admin-staff',studentScope='admin-participants';
  const staffToolbar=discoveryToolbar(staffScope,{placeholder:'Search',filters:[{key:'status',label:'Status',options:[{value:'active',label:'Active'},{value:'inactive',label:'Inactive'}]},{key:'role',label:'Role',options:[{value:'super_admin',label:'Super administrator'},{value:'administrator',label:'Administrator'},{value:'trainer',label:'Trainer'},{value:'assistant',label:'Assistant trainer'},{value:'course_editor',label:'Course Editor'}]}],sorts:[{value:'title:asc',label:'Name A–Z'},{value:'title:desc',label:'Name Z–A'}],countLabel:'Trainers'});
  const studentToolbar=discoveryToolbar(studentScope,{placeholder:'Search',filters:[{key:'status',label:'Status',options:[{value:'active',label:'Active'},{value:'inactive',label:'Inactive'},{value:'demo',label:'Demo'}]}],sorts:[{value:'title:asc',label:'Name A–Z'},{value:'classes:desc',label:'Most classes'}],countLabel:'Participants'});
  const staff=state.staff.map(x=>`<tr data-discovery-item data-search="${esc([x.display_name,x.username,x.email,x.staff_role].filter(Boolean).join(' '))}" data-filter-status="${x.active?'active':'inactive'}" data-filter-role="${esc(x.staff_role||'')}" data-sort-title="${esc(x.display_name||'')}"><td><div class="row-main"><span class="avatar">${esc((x.display_name||'?').split(/\s+/).map(y=>y[0]).slice(0,2).join(''))}</span><div><strong>${esc(x.display_name)}</strong><div class="tiny muted">${esc(x.email||'')}</div></div></div></td><td>${esc(x.username)}</td><td>${esc(t(roleName(x.staff_role)))}</td><td><span class="badge">${esc(t(x.active?'Active':'Inactive'))}</span></td><td><div class="topbar-actions"><button class="btn" data-action="permissions" data-id="${x.id}" ${x.staff_role==='super_admin'&&state.user.staff_role!=='super_admin'?'disabled':''}>${esc(t('Permissions'))}</button><button class="btn" data-action="manage-trainer" data-id="${x.id}" ${x.staff_role==='super_admin'&&state.user.staff_role!=='super_admin'?'disabled':''}>${esc(t('Manage'))}</button></div></td></tr>`).join('');
  const students=state.students.map(x=>`<tr data-discovery-item data-search="${esc([x.display_name,x.username,x.email,x.profile?.organization].filter(Boolean).join(' '))}" data-filter-status="${x.is_demo?'demo':x.active?'active':'inactive'}" data-sort-title="${esc(x.display_name||'')}" data-sort-classes="${Number(x.class_count||0)}"><td><input type="checkbox" data-bulk-student="${x.id}"></td><td><div class="row-main"><span class="avatar">${esc((x.display_name||'?').split(/\s+/).map(y=>y[0]).slice(0,2).join(''))}</span><div><strong>${esc(x.display_name)}</strong><div class="tiny muted">${esc(x.email||'')}</div></div></div></td><td>${esc(x.username)}</td><td>${esc(x.profile?.organization||'—')}</td><td>${Number(x.class_count||0)}</td><td><span class="badge ${x.is_demo?'demo':''}">${esc(t(x.is_demo?'Demo':x.active?'Active':'Inactive'))}</span></td><td><button class="btn" data-action="participant-edit" data-id="${x.id}">${esc(t('Manage'))}</button></td></tr>`).join('');
  document.querySelector('#page').innerHTML=`${head(t(kind==='staff'?'Staff accounts':'Participants'),t(kind==='staff'?'Manage your teaching team and their access.':'Manage staff, participant accounts and profile data.'),`<button class="btn" data-action="bulk-participant-deactivate">${esc(t('Deactivate selected'))}</button><button class="btn" data-action="bulk-participant-activate">${esc(t('Activate selected'))}</button><button class="btn" data-action="add-trainer">${esc(t('Add staff account'))}</button><button class="btn primary" data-action="add-participant">${esc(t('Add participant'))}</button>`)}<section class="collection-section" data-people-section="staff"><div class="section-title-row"><div><div class="eyebrow">${esc(t('Team'))}</div><h2>${esc(t('Trainers'))}</h2></div></div>${staffToolbar}<div class="card collection-card"><div class="table-wrap"><table class="table"><thead><tr><th>${esc(t('Name'))}</th><th>${esc(t('Username'))}</th><th>${esc(t('Role'))}</th><th>${esc(t('Status'))}</th><th></th></tr></thead><tbody data-discovery-scope="${staffScope}">${staff}</tbody></table></div></div></section><section class="collection-section" data-people-section="participants"><div class="section-title-row"><div><div class="eyebrow">${esc(t('Participants'))}</div><h2>${esc(t('Participants'))}</h2></div></div>${studentToolbar}<div class="card collection-card"><div class="table-wrap"><table class="table"><thead><tr><th></th><th>${esc(t('Participant'))}</th><th>${esc(t('Username'))}</th><th>${esc(t('Organization'))}</th><th>${esc(t('Classes'))}</th><th>${esc(t('Status'))}</th><th></th></tr></thead><tbody data-discovery-scope="${studentScope}">${students}</tbody></table></div></div></section>`
  document.querySelectorAll('[data-people-section]').forEach(el=>el.hidden=el.dataset.peopleSection!==kind);
  document.querySelector('[data-action=add-trainer]').hidden=kind!=='staff';
  document.querySelector('[data-action=add-participant]').hidden=kind==='staff';
  document.querySelectorAll('[data-action^=bulk-participant]').forEach(el=>el.hidden=kind==='staff');
}
