  const n=await api('/api/notifications'),scope='admin-messages',toolbar=discoveryToolbar(scope,{placeholder:'Search',filters:[{key:'status',label:'Status',options:[{value:'unread',label:'Unread'},{value:'read',label:'Read'}]}],sorts:[{value:'date:desc',label:'Newest date'},{value:'date:asc',label:'Oldest date'}],countLabel:'Messages'});
